  [439155] = { "革新の魔法の印章を得て、$D1の間、呪文による与えるダメージと回復量を最大$N1増加させ、攻撃力を$N2増加させます。これは戦闘外でのみ使用できます。", "Innovationの力を得ています。呪文によるダメージと治療量が最大$N1増加し、攻撃力が$N2上昇しています。", 0x5b27e1aa, 0x21bf66a3, "uu" },
  [439431] = { "シャーマンの武器に風の力を宿します。攻撃が命中するたびに20%の確率で、近接攻撃力が$N3追加された追加攻撃を$N2回行います。5分間持続します。", nil, 0x97843252, nil, "um" },
  [439462] = { "武器に30分間持続する毒を塗ります。\n攻撃のたびに$N2%の確率で敵を毒に冒し、$D1の間、敵のアーマーを$N3低下させます。\n\nSebacious PoisonはImproved Expose Armorのタレントの効果を受けます。", nil, 0x2d0ef69d, nil, "um" },
  [439464] = { "武器に30分間持続する毒を塗ります。\n攻撃のたびに$N2%の確率で敵を毒に冒し、$D1の間、敵の近接攻撃の間隔を$N3%延ばします。", nil, 0x706228c1, nil, "um" },
  [439465] = { "武器に30分間持続する毒を塗ります。\n攻撃のたびに$N2%の確率で敵を毒に冒し、$D1の間、敵の近接攻撃力を$N3低下させます。", nil, 0x97dc5dec, nil, "um" },
