  [439473] = { nil, "近接攻撃力が$N1低下しています。", nil, 0x100ea0c6, "mu" },
  [439500] = { "武器に30分間持続する毒を塗ります。\n攻撃のたびに$N2%の確率で敵を毒に冒し、$D1の間、敵のアーマーを$N3低下させます。チャージ105回。\n\nSebacious PoisonはImproved Expose Armorのタレントの効果を受けます。", nil, 0xa3ff8443, nil, "um" },
  [439503] = { "武器に30分間持続する毒を塗ります。\n攻撃のたびに$N2%の確率で敵を毒に冒し、$D1の間、敵の近接攻撃力を$N3低下させます。チャージ105回。", nil, 0xebede533, nil, "um" },
  [439505] = { "武器に30分間持続する毒を塗ります。\n攻撃のたびに$N2%の確率で敵を毒に冒し、$D1の間、敵の近接攻撃の間隔を$N3%延ばします。チャージ105回。", nil, 0x05dfb154, nil, "um" },
  [439510] = { "Cat Formの間はSwipeのアビリティがSwipe (Cat)になり、Bear Formの間はSwipeのアビリティが追加の敵最大$N1体に命中するようになります。\n\nSwipe (Cat)\n$I1\n近くの敵を薙ぎ払い、武器ダメージの$N2%を与え、現在の対象にコンボポイントを$N3獲得します。", nil, 0x7f92f961, nil, "um" },
  [439651] = { "Fist Weaponsが+$N1上昇します。", nil, 0xcffc0304, nil, "um" },
  [439691] = { "プレイヤーをGnomereganへ送ります。", nil, 0x187b8984, nil, "um" },
  [439733] = { "Tree of Lifeに変身します。この形態の間、$N2ヤード以内のすべてのパーティーメンバーが受ける治癒が$N1%増加し、Wild Growthの回復量が$N3%増加し、継続回復呪文のコストが$N4%減少し、精神が$N5%増加し、アーマーが$N6%増加しますが、有害な呪文は詠唱できません。\n\n変身すると、術者はPolymorphとMovement Impairingの効果から解放されます。", "Polymorph効果に対する免疫があります。\n継続回復呪文のマナコストが$N1%減少します。\n精神が$N2%、アーマーが$N3%増加します。\n$N5ヤード以内のすべてのパーティーメンバーの受ける回復量が$N4%増加し、Wild Growthの回復量が$N6%増加します。", 0xc887c72f, 0x3b08cc5b, "uu" },
  [439745] = { "$N1ヤード以内のパーティーメンバーが受けるすべての治癒が$N2%増加しました。", "受ける回復量が$N1%増加します。", 0x29dc8839, 0xec4c26b6, "uu" },
  [439748] = { "$D1かけて空から星の雨を呼び寄せ、自分の位置から$N2ヤード以内の対象を打ちます。星はそれぞれ対象に$N3～$N4のArcaneダメージを与え、その$N6ヤード以内にいる他のすべての敵に$N5のArcaneダメージを与えます。星は最大20個です。\n\n変身または騎乗すると効果は解除されます。キャラクターの操作を失わせる効果を受けると、Starfallの効果は抑えられます。\n\nMoonfireが発動させる、またはMoonfireの恩恵を受けるほとんどのタレントと効果の恩恵を受け、それらを発動させます。", "空から星を呼び寄せています。", 0x16bd2a8d, 0xe60f8fbc, "uu" },
  [439753] = { "術者から30ヤード以内のすべての対象に空から星の雨を呼び寄せ、星はそれぞれ$N2のArcaneダメージを与えます。さらに、敵の対象から$N4ヤード以内にいる他のすべての敵にも$N3のArcaneダメージを与えます。星は最大20個です。効果時間は$D1です。", "術者の$N1ヤード以内にいるすべての目標に空から星を降り注がせ、それぞれ$N2のArcaneダメージを与えます。さらに、敵の目標から$N4ヤード以内にいる他のすべての敵にも$N3のArcaneダメージを与えます。星は最大$N5個。$D1持続します。", 0xe6e31d13, 0xe6e31d13, "uu" },
  [439756] = { nil, "星は最大$N1個。$D1持続します。", nil, 0x1ae310a7, "mu" },
  [439765] = { "外套にImproved Swipeのルーンを刻みます：\n\n$I1\nCat Form中はSwipeがSwipe (Cat)になり、Bear Form中はSwipeが追加で最大$N1体の敵を攻撃します。\n\nSwipe (Cat)\n$I2\n近くの敵をなぎ払い、武器ダメージの$N2%を与え、現在の対象へのコンボポイントを$N3生み出します。", nil, 0xe1173b73, nil, "um" },
  [439766] = { "Tree of Lifeのアビリティを得ます：\n\n$I1\nTree of Lifeに変身します。この形態の間、$N2ヤード以内のすべてのパーティーメンバーが受ける治癒が$N1%増加し、Wild Growthの回復量が$N3%増加し、継続回復呪文のコストが$N4%減少し、精神が$N5%増加し、アーマーが$N6%増加しますが、有害な呪文は詠唱できません。\n\n変身すると、術者はPolymorphとMovement Impairingの効果から解放されます。", nil, 0x26efaedb, nil, "um" },
  [439767] = { "外套にTree of Lifeのルーンを刻みます：\n\n$I1\nTree of Lifeに変身します。この姿の間、$N2ヤード以内のパーティーメンバー全員の受ける回復量が$N1%増加し、Wild Growthの回復量が$N3%増加し、持続回復呪文のコストが$N4%減少し、精神が$N5%増加し、アーマーが$N6%増加しますが、有害な呪文は詠唱できません。\n\n変身するとPolymorphとMovement Impairing効果から解放されます。", nil, 0x33ad400e, nil, "um" },
  [439768] = { "Starfallのアビリティを得ます：\n\n$I1\n$D1かけて空から星の群れを呼び寄せ、自分の位置から$N2ヤード以内の対象を攻撃します。星はそれぞれ対象に$N3のArcaneダメージを、$N5ヤード以内の他のすべての敵に$N4のArcaneダメージを与えます。星は最大20個です。\n\n変身するか騎乗すると、この効果は解除されます。キャラクターの操作を失う効果を受けると、Starfallの効果は抑制されます。\n\nMoonfireから発動する、またはその恩恵を受ける大半の才能と効果の恩恵を受け、それらを発動させます。", nil, 0x29e92378, nil, "um" },
  [439770] = { "外套にStarfallのルーンを刻みます：\n\n$I1\n$D1かけて空から星の雨を降らせ、自分の位置から$N2ヤード以内の対象を攻撃します。星はそれぞれ対象に$N3のArcaneダメージを与え、$N5ヤード以内の他のすべての敵に$N4のArcaneダメージを与えます。星は最大20個です。\n\n変身または騎乗すると効果は解除されます。キャラクターの操作を失う効果を受けると、Starfallの効果は抑制されます。\n\nMoonfireから発動する、またはMoonfireに恩恵を与えるほとんどのタレントと効果の恩恵を受け、それらを発動させます。", nil, 0x49741463, nil, "um" },
  [439958] = { nil, "Blood Loaは危険に報います。", nil, 0x548d5a62, "mu" },
  [439959] = { "$D1の間、呪文のダメージを最大$N1上げます。", "呪文とアビリティによる魔法ダメージが最大$N1増加します。", 0xbfd948e7, 0xa5bf5341, "uu" },
